func newConfigCommand(env EntireEnv) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "config",
		Short: "Inspect or initialize plugin configuration",
	}

	cmd.AddCommand(&cobra.Command{
		Use:   "path",
		Short: "Print the plugin config path",
		RunE: func(cmd *cobra.Command, args []string) error {
			path, err := configPath(env)
			if err != nil {
				return err
			}
			fmt.Fprintln(cmd.OutOrStdout(), path)
			return nil
		},
	})

	cmd.AddCommand(&cobra.Command{
		Use:   "show",
		Short: "Print plugin configuration as JSON",
		RunE: func(cmd *cobra.Command, args []string) error {
			dataDir, err := requireDataDir(env)
			if err != nil {
				return err
			}
			cfg, err := config.Load(dataDir)
			if err != nil {
				return err
			}
			encoded, err := json.MarshalIndent(cfg, "", "  ")
			if err != nil {
				return err
			}
			fmt.Fprintln(cmd.OutOrStdout(), string(encoded))
			return nil
		},
	})

	cmd.AddCommand(&cobra.Command{
		Use:   "init",
		Short: "Write the default plugin configuration",
		RunE: func(cmd *cobra.Command, args []string) error {
			dataDir, err := requireDataDir(env)
			if err != nil {
				return err
			}
			if err := config.Save(dataDir, config.Default()); err != nil {
				return err
			}
			path, err := config.Path(dataDir)
			if err != nil {
				return err
			}
			fmt.Fprintf(cmd.OutOrStdout(), "wrote %s\n", path)
			return nil
		},
	})

	return cmd
}

func configPath(env EntireEnv) (string, error) {
	dataDir, err := requireDataDir(env)
	if err != nil {
		return "", err
	}
	return config.Path(dataDir)
}

func requireDataDir(env EntireEnv) (string, error) {
	if env.PluginDataDir == "" {
		return "", errors.New("ENTIRE_PLUGIN_DATA_DIR is unset; run through `entire plugin-template` or set it for local testing")
	}
	return env.PluginDataDir, nil
}
package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

func newDoctorCommand(env EntireEnv) *cobra.Command {
	return &cobra.Command{
		Use:   "doctor",
		Short: "Check the parent Entire CLI plugin environment",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runDoctor(cmd, env)
		},
	}
}

func runDoctor(cmd *cobra.Command, env EntireEnv) error {
	out := cmd.OutOrStdout()
	fmt.Fprintf(out, "ENTIRE_CLI_VERSION=%s\n", valueOrUnset(env.CLIVersion))
	fmt.Fprintf(out, "ENTIRE_REPO_ROOT=%s\n", valueOrUnset(env.RepoRoot))
	fmt.Fprintf(out, "ENTIRE_PLUGIN_DATA_DIR=%s\n", valueOrUnset(env.PluginDataDir))

	if env.PluginDataDir == "" {
		return errors.New("ENTIRE_PLUGIN_DATA_DIR is unset; run through `entire plugin-template` or set it for local testing")
	}
	if err := os.MkdirAll(env.PluginDataDir, 0o700); err != nil {
		return fmt.Errorf("create plugin data dir: %w", err)
	}

	f, err := os.CreateTemp(env.PluginDataDir, ".write-test-*")
	if err != nil {
		return fmt.Errorf("write plugin data dir: %w", err)
	}
	name := f.Name()
	if err := f.Close(); err != nil {
		return fmt.Errorf("close write probe: %w", err)
	}
	if err := os.Remove(name); err != nil {
		return fmt.Errorf("remove write probe: %w", err)
	}

	fmt.Fprintln(out, "plugin data dir: writable")
	return nil
}
package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

type Config struct {
	Greeting string `json:"greeting"`
}

func Default() Config {
	return Config{Greeting: "Hello from an Entire plugin"}
}

func Path(dataDir string) (string, error) {
	if dataDir == "" {
		return "", errors.New("plugin data dir is empty")
	}
	return filepath.Join(dataDir, "config.json"), nil
}

func Load(dataDir string) (Config, error) {
	path, err := Path(dataDir)
	if err != nil {
		return Config{}, err
	}

	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return Default(), nil
		}
		return Config{}, fmt.Errorf("read config: %w", err)
	}

	var cfg Config
	if err := json.Unmarshal(data, &cfg); err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if cfg.Greeting == "" {
		cfg.Greeting = Default().Greeting
	}
	return cfg, nil
}

func Save(dataDir string, cfg Config) error {
	path, err := Path(dataDir)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("create config dir: %w", err)
	}
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return fmt.Errorf("encode config: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o600); err != nil {
		return fmt.Errorf("write config: %w", err)
	}
	return nil
}

